source.excerpt:
\begin{intro}
You may be familiar with different terminology and symbols than the
ones we use above. Logic texts (and teachers) commonly use either
$\sim$, $\neg$, and~!\ for ``negation'', $\wedge$, $\cdot$, and $\&$
for ``conjunction''.  Commonly used symbols for the ``conditional'' or
``implication'' are $\rightarrow$, $\Rightarrow$, and $\supset$.
\iftag{prvIff,defIff}{Symbols for ``biconditional,'' ``bi-implication,''
  or ``(material) equivalence'' are $\leftrightarrow$,
  $\Leftrightarrow$, and $\equiv$.}{}
\iftag{prvFalse,defFalse}{The $\lfalse$ symbol is variously called
  ``falsity,'' ``falsum,'' ``absurdity,'' or ``bottom.''}{}
\iftag{prvTrue,defTrue}{The $\ltrue$ symbol is variously called
  ``truth,'' ``verum,'' or ``top.''}{}
\end{intro}

target.excerpt:
\begin{intro}
ہو سکدا اے تُسی اُتّے ساڈی ورتی اصطلاح تے علامات توں وکھری اصطلاح تے
علامتاں نال واقف ہووو۔ منطق دیاں کتاباں (تے استاد) ``نفی'' لئی عام طور
تے $\sim$، $\neg$ تے~!\ ورتدے نیں، تے ``عطف'' لئی $\wedge$،
$\cdot$ تے $\&$۔ ``شرطیہ'' یا ``لزوم'' لئی عام ورتیاں جان والیاں
علامتاں $\rightarrow$، $\Rightarrow$ تے $\supset$ نیں۔
\iftag{prvIff,defIff}{``دو شرطیہ''، ``دو طرفہ لزوم'' یا ``(مادی) ہم
  ارزی'' دیاں علامات $\leftrightarrow$، $\Leftrightarrow$ تے
  $\equiv$ نیں۔}{}
\iftag{prvFalse,defFalse}{$\lfalse$ دی علامت نوں وکھ وکھ تھاواں اُتے
  ``کذب''، ``کاذب''، ``محال'' یا ``زیریں'' آکھیا جاندا اے۔}{}
\iftag{prvTrue,defTrue}{$\ltrue$ دی علامت نوں وکھ وکھ تھاواں اُتے
  ``صدق''، ``صادق'' یا ``بالائی'' آکھیا جاندا اے۔}{}
\end{intro}

