source.excerpt:
\begin{tagblock}{compsci}
\begin{ex}[Strings] 
Another interesting example  is the set $A^{*}$ of \emph{finite
strings} over an alphabet $A$: any finite sequence of elements of~$A$
is a string over $A$. We include the \emph{empty string $\Lambda$}
among the strings over~$A$, for every alphabet~$A$. For instance,
\begin{multline*}
\Bin^*
=\{\Lambda,0,1,00,01,10,11,\\
000,001,010,011,100,101,110,111,0000,\ldots\}.
\end{multline*}
If $x=x_{1}\ldots x_{n}\in A^{*}$is a string consisting of $n$
``letters'' from $A$, then we say \emph{length} of the string is~$n$
and write $\len{x}=n$.
\end{ex}
\end{tagblock}

target.excerpt:
\begin{tagblock}{compsci}
\begin{ex}[لڑیاں]
اک ہور دلچسپ مثال سیٹ $A^{*}$ اے، جہڑا حرفاں دے مجموعے $A$ اُتے
\emph{محدود لڑیاں} دا سیٹ اے: $A$ دے عنصراں دا کوئی وی محدود سلسلہ، $A$ اُتے
اک لڑی اے۔ اسی \emph{خالی لڑی $\Lambda$} نوں وی $A$ اُتے بنن والیاں لڑیاں وچ
شامل کردے آں، ہر حرفی مجموعے~$A$ لئی۔ مثال لئی،
\begin{multline*}
\Bin^*
=\{\Lambda,0,1,00,01,10,11,\\
000,001,010,011,100,101,110,111,0000,\ldots\}.
\end{multline*}
جے $x=x_{1}\ldots x_{n}\in A^{*}$ اک لڑی ہووے جہدے وچ $n$ ``حرف'' ہون،
جو $A$ توں لئے گئے ہون، تاں اسی آکھدے آں کہ لڑی دی \emph{لمبائی}~$n$ اے تے
$\len{x}=n$ لکھدے آں۔
\end{ex}
\end{tagblock}

