\begin{defn}
If $A$ is a set of sets, then $\bigcup A$ is the set of !!{element}s of
!!{element}s of~$A$:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ belongs to !!a{element} of } A},
\text{ i.e.,}\\
& = \Setabs{x}{\text{there is a } B \in A
  \text{ so that } x \in B}
\end{align*}
\end{defn}

target.excerpt:
\begin{defn}
جے $A$ سیٹاں دا سیٹ اے، تاں $\bigcup A$، سیٹ~$A$ دے
\pnboblique{!!{element}s} دے \pnboblique{!!{element}s} دا سیٹ اے:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{، سیٹ } A\text{ دے کسے !!a{element} دا عنصر اے}},
\text{ یعنی،}\\
& = \Setabs{x}{\text{کوئی } B \in A
  \text{ ایہو جہا اے کہ } x \in B}
\end{align*}
\end{defn}

