source.excerpt:
\begin{defn}
A tree $T = \tuple{A, \le}$ is said to be \emph{infinite} if $A$ is an
infinite set, and \emph{finite} otherwise. If $T$ is such that every
$x \in A$ has only finitely many successors, then we say that $T$ is
\emph{finitely branching}.
\end{defn}

target.excerpt:
\begin{defn}
درخت $T = \tuple{A, \le}$ \emph{لامتناہی} آکھلاندا اے جے $A$ لامتناہی
سیٹ ہووے، تے نہیں تاں \emph{محدود}۔ جے $T$ ایہو جیہا ہووے کہ ہر
$x \in A$ دے صرف محدود گنتی وچ جانشین ہون، تاں اسی آکھدے آں کہ $T$
\emph{ہر گرہ اُتے محدود شاخاں والا} اے۔
\end{defn}

source.excerpt:
\begin{prop}\ollabel{prop:graph-function}
Let $R \subseteq A \times B$ be such that:
\begin{enumerate}
\item If $Rxy$ and $Rxz$ then $y = z$; and 
\item for every $x \in A$ there is some $y \in B$ such that $\tuple{x,
y} \in R$.  
\end{enumerate}
Then $R$ is the graph of the function $f\colon A \to B$ defined by
$f(x) = y$ iff $Rxy$. 
\end{prop}

target.excerpt:
\begin{prop}\ollabel{prop:graph-function}
من لو کہ $R \subseteq A \times B$ ایس طرح اے کہ:
\begin{enumerate}
\item جے $Rxy$ تے $Rxz$، تاں $y = z$؛ تے
\item ہر $x \in A$ لئی کوئی $y \in B$ اے جیہدے لئی $\tuple{x,
y} \in R$۔
\end{enumerate}
فیر $R$ اوس فنکشن $f\colon A \to B$ دا گراف اے جیہڑا
$f(x) = y$ عین اوس ویلے جدوں $Rxy$ راہیں تعریف ہوندا اے۔
\end{prop}

