وکھاؤ کہ جے $f\colon A \to B$ دا کھبا اُلٹ~$g$ اے، تاں~$f$،
!!{injective} اے۔
\end{prob}

source.excerpt:
\begin{prop}
    If $f\colon A \to B$ is !!{surjective}, then there is a
    \emph{right inverse}~$h\colon B \to A$ of~$f$ so that $f(h(y)) =
    y$ for all~$y \in B$.
\end{prop}

target.excerpt:
\begin{prop}
    جے $f\colon A \to B$، !!{surjective} اے، تاں اک
