source.excerpt:
\begin{explain}
  By combining the ideas in the previous proof, we now get that every
  !!{bijection} has an inverse, i.e., there is a single function
  which is both a left and right inverse of~$f$.
\end{explain}

target.excerpt:
\begin{explain}
  پچھلے ثبوت دے خیالاں نوں اکٹھا کرکے سانوں ہُن ایہ ملدا اے کہ ہر
  !!{bijection} دا اک اُلٹ ہوندا اے، یعنی اک اکو فنکشن جیہڑا~$f$
  دا کھبا اُلٹ وی اے تے سجا اُلٹ وی۔
\end{explain}

source.excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
If $f\colon A \to B$ is !!{bijective}, there is a
function~$f^{-1}\colon B \to A$ so that for all $x \in A$,
$f^{-1}(f(x)) = x$ and for all $y \in B$, $f(f^{-1}(y)) = y$.
\end{prop}

target.excerpt:
\begin{prop}\ollabel{prop:bijection-inverse}
جے $f\colon A \to B$، !!{bijective} اے، تاں اک
فنکشن~$f^{-1}\colon B \to A$ اے جیہدے لئی ہر $x \in A$ اُتے
$f^{-1}(f(x)) = x$ تے ہر $y \in B$ اُتے $f(f^{-1}(y)) = y$۔
\end{prop}

source.excerpt:
\begin{prob}
Prove \olref[sfr][fun][inv]{prop:bijection-inverse}. You have to
define~$f^{-1}$, show that it is a function, and show that it is an
inverse of~$f$, i.e., $f^{-1}(f(x)) = x$ and $f(f^{-1}(y)) = y$ for
all $x \in A$ and $y \in B$.
\end{prob}

target.excerpt:
\begin{prob}
\olref[sfr][fun][inv]{prop:bijection-inverse} ثابت کرو۔ تہانوں
~$f^{-1}$ تعریف کرنا اے، وکھاؤنا اے کہ ایہ فنکشن اے، تے وکھاؤنا
اے کہ ایہ~$f$ دا اُلٹ اے، یعنی $f^{-1}(f(x)) = x$ تے
$f(f^{-1}(y)) = y$، ہر $x \in A$ تے $y \in B$ لئی۔
\end{prob}

\begin{explain}
اُلٹ کڈھن دا اک ذرا ہور عام طریقہ وی اے۔ اسی \olref[kin]{sec} وچ
ویکھیا سی کہ ہر فنکشن $f$ اک !!a{surjection}
$f' \colon A \to \ran{f}$ پیدا کردا اے، $f'(x) = f(x)$ رکھ کے ہر
$x \in A$ لئی۔ صاف اے
کہ جے $f$، !!{injective} اے، تاں $f'$، !!{bijective} اے، سو
\olref{prop:bijection-inverse} موجب اوہدا اک اکلوتا اُلٹ اے۔ علامت
دی اک بہت چھوٹی جیہی ڈھیل نال اسی کدی کدی $f'$ دے اُلٹ نوں بس
``~$f$ دا اُلٹ'' آکھ دیندے آں۔
\end{explain}

\begin{explain}
\oliflabeldef{sfr:fun:inv:sec}{اسی \olref[inv]{sec} وچ ویکھیا سی
کہ اُلٹ~$f^{-1}$، !!a{bijection}~$f$ دا، آپ وی اک فنکشن اے۔}{}
فنکشناں اُتے ہور عمل ترکیب اے: اسی دو فنکشناں، $f$ تے~$g$، نوں
ترتیب نال لاگو کرکے نواں فنکشن تعریف کر سکدے آں، یعنی پہلے $f$ تے
فیر~$g$ لاگو کرکے۔ بے شک، ایہ صرف اوس ویلے ممکن اے جدوں حاصل قدراں
دا سیٹ تے دائرۂ تعریف میل کھاندے ہون، یعنی~$f$ دا حاصل قدراں دا سیٹ
~$g$ دے دائرۂ تعریف دا ذیلی سیٹ ہونا چاہیدا اے۔
\oliflabeldef{sfr:rel:ops:sec}{فنکشناں اُتے ایہ عمل، تعلقاں اُتے
\olref[rel][ops]{sec} والے نسبتی حاصل ضرب دے عمل دا مماثل اے۔}{}

