\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

target.excerpt:
\begin{defn}
  \ollabel{defn:enumerable}
  سیٹ~$A$، !!{enumerable} عین اوس ویلے اے جدوں یا تاں
  $A = \emptyset$ ہووے یا~$A$ دی کوئی گنتی وار فہرست موجود ہووے۔
  اسی~$A$ نوں !!{nonenumerable} عین اوس ویلے آکھدے آں جدوں~$A$،
  !!{enumerable} نہ ہووے۔
\end{defn}

