source.excerpt:
\begin{thm}[Arithmetical induction]\ollabel{thm:dedinfiniteinduction}
Let $N, s, o$ comprise a Dedekind algebra. Then for any set $X$:  
	\begin{center}
		if $o \in X$ and $(\forall {n} \in N \cap X){s}({n}) \in X$, {then} $N \subseteq X$.
	\end{center}
\end{thm}

target.excerpt:
\begin{thm}[حسابی استقرا]\ollabel{thm:dedinfiniteinduction}
$N, s, o$ رل کے اک ڈیڈیکائنڈ الجبرا بناؤن۔ فیر ہر سیٹ $X$ لئی:
	\begin{center}
		جے $o \in X$ تے $(\forall {n} \in N \cap X){s}({n}) \in X$، {تاں} $N \subseteq X$۔
	\end{center}
\end{thm}

source.excerpt:
\begin{cor}\ollabel{natinductionschema}
Let $N, s, o$ comprise a Dedekind algebra. Then for any formula
$\phi(x)$, which may have parameters:
\begin{center}
	if $\phi(o)$ and $(\forall {n} \in N)(\phi(n)\lif
	\phi({s}({n})))$, {then} $(\forall n \in N)\phi(n)$
\end{center}
\end{cor}

target.excerpt:
\begin{cor}\ollabel{natinductionschema}
$N, s, o$ رل کے اک ڈیڈیکائنڈ الجبرا بناؤن۔ فیر ہر فارمولے
$\phi(x)$ لئی، جیہدے وچ پیرامیٹر ہو سکدے نیں:
\begin{center}
	جے $\phi(o)$ تے $(\forall {n} \in N)(\phi(n)\lif
	\phi({s}({n})))$، {تاں} $(\forall n \in N)\phi(n)$
\end{center}
\end{cor}

